sealed trait Backend
object Backend { case object Postgres extends Backend; case object Sqlite extends Backend }

trait UserDao { def find(id: Long): IO[Option[User]] }

object UserDao {
  def apply(backend: Backend, xa: Transactor[IO]): UserDao = backend match {
    case Backend.Postgres => new PgUserDao(xa)
    case Backend.Sqlite   => new SqliteUserDao(xa)
  }
}
